CREATE TABLE IF NOT EXISTS user_voice_library (uid TEXT NOT NULL, voice_id TEXT NOT NULL, name TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'design', tag TEXT, dialect TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (uid, voice_id)); ALTER TABLE user_voice_library ENABLE ROW LEVEL SECURITY; CREATE POLICY user_voice_library_isolation ON user_voice_library USING (uid = current_setting('request.jwt.claims.uid', true)); COMMENT ON TABLE user_voice_library IS '每用户音色库（多设备同步）：创造/克隆/收藏音色的命名与列表，PK=(uid,voice_id)，重名检查由后端代码保证';
